<?php namespace App\Http\Controllers\Api\V1; use Illuminate\Http\Request; use App\Models\{StudentFee,Attendance,Notice,Timetable}; class AiAssistantController extends Controller {public function query(Request $r){$d=$r->validate(['query'=>'required|string|max:2000']);$q=strtolower($d['query']);$u=$r->user();$result=['intent'=>'general','answer'=>'I can help with authorized school information.'];if(str_contains($q,'fee')){if(in_array($u->role?->slug,['teacher'],true))return $this->fail('You are not authorized to access fee information.',403);$result=['intent'=>'fees','answer'=>'Fee information retrieved.','data'=>StudentFee::where('school_id',$u->school_id)->limit(20)->get()];}elseif(str_contains($q,'attendance')){$result=['intent'=>'attendance','answer'=>'Attendance information retrieved.','data'=>Attendance::where('school_id',$u->school_id)->latest()->limit(20)->get()];}elseif(str_contains($q,'notice')){$result=['intent'=>'notices','answer'=>'Relevant notices retrieved.','data'=>Notice::where('school_id',$u->school_id)->latest()->limit(20)->get()];}elseif(str_contains($q,'timetable')){$result=['intent'=>'timetable','answer'=>'Timetable information retrieved.','data'=>Timetable::where('school_id',$u->school_id)->limit(50)->get()];}return $this->ok($result);}}
